                },
                "start_date": {
                    "type": "string",
                    "format": "date"
                },
                "end_date": {
                    "type": "string",
                    "format": "date"
                }
            },
            "required": [
                "code",
                "code_scheme_id"
            ]
        },
        "previous-name": {
