                },
                "jurisdiction_code": {
                    "type": "string",
                    "description": "Code representing the jurisdiction/company register which is the canonical record of the company\u2019s existence. Uses underscored ISO 3166-2 to represent it, e.g. es for Spain, us_de for Delaware",
                    "minLength": 2,
                    "maxLength": 5
                },
                "incorporation_date": {
                    "type": "string",
                    "format": "date"
                },
                "dissolution_date": {
                    "type": "string",
                    "format": "date"
                },
                "retrieved_at": {
                    "type": "string",
                    "format": "date"
                },
                "current_status": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "company_type": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "registry_url": {
                    "type": "string"
                },
                "website": {
                    "oneOf": [
                        {
                            "type": "string",
