                        {
                            "type": [
                                "array",
                                "null"
                            ],
                            "items": {
                                "type": "string",
                                "minLength": 5
                            }
                        }
                    ]
                },
                "telephone_number": {
                    "type": "string",
                    "minLength": 4
                },
                "fax_number": {
                    "type": "string",
                    "minLength": 4
                },
                "registered_address": {
                    "$ref": "#/definitions/address"
                },
