                                    "anyOf": [
                                        {
                                            "required": [
                                                "name"
                                            ]
                                        },
                                        {
                                            "required": [
                                                "company_number"
                                            ]
                                        }
                                    ]
                                },
                                "effective_date": {
                                    "description": "The date of the merger",
                                    "type": "string",
                                    "format": "date"
                                }
                            },
                            "additionalProperties": false,
                            "required": [
                                "surviving_company"
                            ]
                        }
                    }
                }
            },
            "additionalProperties": false,
            "anyOf": [
                {
                    "required": [
                        "name"
                    ]
                },
                {
                    "required": [
                        "company_number"
                    ]
                }
            ]
