                "label": {
                    "type": "string",
                    "description": "The name of the goto target (shown in the UI)."
                },
                "line": {
                    "type": "integer",
                    "description": "The line of the goto target."
                },
                "column": {
                    "type": "integer",
                    "description": "An optional column of the goto target."
