            "$ref": "#/definitions/Organization",
            "description": "The buyer is the entity whose budget will be used to purchase the goods. This may be different from the procuring agency who may be specified in the tender data.",
            "title": "Buyer"
        },
        "contracts": {
            "description": "Information from the contract creation phase of the procurement process.",
            "items": {
                "$ref": "#/definitions/Contract"
            },
            "mergeOptions": {
                "idRef": "id"
            },
            "mergeStrategy": "arrayMergeById",
            "title": "Contracts",
            "type": "array",
            "_uniqueItems": true
        },
        "date": {
            "_format": "date-time",
            "description": "The date this information is released, it may well be the same as the parent publishedDate, it must not be later than the publishedDate from the parent package. It is used to determine merge order.",
            "mergeStrategy": "ocdsOmit",
            "title": "Release Date",
            "type": "string"
        },
        "id": {
            "description": "A unique identifier that identifies this release. A releaseID must be unique within a release-package and must not contain the # character.",
            "mergeStrategy": "ocdsOmit",
            "title": "Release ID",
            "type": "string"
        },
        "initiationType": {
            "description": "String specifying the type of initiation process used for this contract, taken from the [initiationType](http://ocds.open-contracting.org/standard/r/1__0__RC/en/schema/codelists#initiation-type) codelist. Currently only tender is supported.",
            "enum": [
                "tender"
            ],
            "mergeStrategy": "ocdsVersion",
            "title": "Initiation type",
            "type": "string"
        },
        "language": {
            "default": "en",
            "description": "Specifies the default language of the data using either two-digit ISO 639-1, or extended BCP47 language tags. The use of two-letter codes from ISO 639-1 is strongly recommended.",
            "mergeStrategy": "ocdsVersion",
            "title": "Release language",
            "type": [
                "string",
                "null"
            ]
        },
        "ocid": {
            "description": "A globally unique identifier for this Open Contracting Process. Composed of a publisher prefix and an identifier for the contracting process. For more information see the [Open Contracting Identifier guidance](http://ocds.open-contracting.org/standard/r/1__0__RC/en/key_concepts/identifiers/#ocid)",
            "mergeStrategy": "ocdsOmit",
            "title": "Open Contracting ID",
            "type": "string"
        },
        "planning": {
            "$ref": "#/definitions/Planning",
            "description": "Information from the planning phase of the contracting process. This includes information related to the process of deciding what to contract for, when and how.",
            "title": "Planning"
        },
        "tag": {
            "description": "A value from the [releaseTag codelist](http://ocds.open-contracting.org/standard/r/1__0__RC/en/schema/codelists#release-tag) that identifies the nature of the release being made. Tags may be used to filter release, or, in future, for for advanced validation when certain kinds of releases should contain certain fields.",
            "items": {
                "enum": [
                    "planning",
                    "tender",
                    "tenderAmendment",
                    "tenderUpdate",
                    "tenderCancellation",
                    "award",
                    "awardUpdate",
                    "awardCancellation",
                    "contract",
                    "contractUpdate",
                    "contractAmendment",
                    "implementation",
                    "implementationUpdate",
                    "contractTermination",
                    "compiled"
                ],
                "type": "string"
            },
            "mergeStrategy": "ocdsOmit",
            "title": "Release Tag",
            "type": "array"
        },
        "tender": {
            "$ref": "#/definitions/Tender",
            "description": "The activities undertaken in order to enter into a contract.",
            "title": "Tender"
        }
    },
    "required": [
        "ocid",
        "id",
        "date",
        "tag",
        "initiationType"
    ],
    "title": "Schema for an Open Contracting Release",
    "type": "object"
}

