                },
                "tags-path": {
                    "type": [
                        "string",
                        "boolean"
                    ]
                },
                "package-path": {
                    "type": "string"
                },
                "depot": {
                    "type": "string"
                },
                "branch": {
                    "type": "string"
                },
                "unique_perforce_client_name": {
                    "type": "string"
                },
                "p4user": {
                    "type": "string"
                },
                "p4password": {
                    "type": "string"
                }
            }
        },
        "path-repository": {
            "type": "object",
