                        "path"
                    ]
                },
                "url": {
                    "type": "string"
                },
                "options": {
                    "type": "object",
                    "properties": {
                        "symlink": {
                            "type": [
                                "boolean",
                                "null"
                            ]
                        }
                    },
                    "additionalProperties": true
                }
