        "artifact-repository": {
            "type": "object",
            "required": [
                "type",
                "url"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "artifact"
                    ]
                },
                "url": {
                    "type": "string"
                }
            }
        },
        "pear-repository": {
            "type": "object",
            "required": [
                "type",
                "url"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
