                            },
                            "required": [
                                "reason",
                                "breakpoint"
                            ]
                        }
                    },
                    "required": [
                        "event",
                        "body"
                    ]
                }
            ]
        },
        "ModuleEvent": {
            "allOf": [
                {
                    "$ref": "#/definitions/Event"
                },
