{
    "id": "http://standard.open-contracting.org/schema/1__0__3/versioned-release-validation-schema.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Schema for a compiled, versioned Open Contracting Release.",
    "type": "object",
    "properties": {
        "initiationType": {
            "items": {
                "properties": {
                    "releaseTag": {
                        "items": {
                            "type": "string"
                        },
                        "type": "array"
                    },
                    "releaseID": {
                        "type": "string"
                    },
                    "releaseDate": {
                        "type": "string",
                        "format": "date-time"
                    },
                    "value": {
                        "type": "string",
                        "enum": [
                            "tender"
                        ]
                    }
                }
            },
            "type": "array"
        },
        "planning": {
            "$ref": "#/definitions/Planning"
        },
        "tender": {
            "$ref": "#/definitions/Tender"
        },
        "buyer": {
            "$ref": "#/definitions/Organization"
        },
        "awards": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/Award"
            },
            "_uniqueItems": true
        },
        "contracts": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/Contract"
            },
            "_uniqueItems": true
        },
        "language": {
            "$ref": "#/definitions/StringNullVersioned"
        },
        "ocid": {
            "title": "Open Contracting ID",
            "description": "A globally unique identifier for this Open Contracting Process. Composed of a publisher prefix and an identifier for the contracting process. For more information see the [Open Contracting Identifier guidance](http://standard.open-contracting.org/1.0/en/schema/identifiers/)",
            "type": "string",
            "mergeStrategy": "ocdsOmit"
        }
    },
    "required": [
        "ocid",
        "initiationType"
    ],
    "definitions": {
        "Planning": {
            "type": "object",
            "properties": {
                "budget": {
                    "$ref": "#/definitions/Budget"
                },
                "rationale": {
                    "$ref": "#/definitions/StringNullVersioned"
                },
                "documents": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/Document"
                    }
                }
            },
            "patternProperties": {
                "^(rationale_(((([A-Za-z]{2,3}(-([A-Za-z]{3}(-[A-Za-z]{3}){0,2}))?)|[A-Za-z]{4}|[A-Za-z]{5,8})(-([A-Za-z]{4}))?(-([A-Za-z]{2}|[0-9]{3}))?(-([A-Za-z0-9]{5,8}|[0-9][A-Za-z0-9]{3}))*(-([0-9A-WY-Za-wy-z](-[A-Za-z0-9]{2,8})+))*(-(x(-[A-Za-z0-9]{1,8})+))?)|(x(-[A-Za-z0-9]{1,8})+)))$": {
                    "type": [
                        "string",
                        "null"
                    ]
                }
            }
        },
        "Tender": {
            "type": "object",
            "required": [
                "id"
            ],
            "properties": {
                "id": {
                    "items": {
                        "properties": {
                            "releaseTag": {
                                "items": {
                                    "type": "string"
                                },
                                "type": "array"
                            },
                            "releaseID": {
                                "type": "string"
                            },
                            "releaseDate": {
                                "type": "string",
                                "format": "date-time"
                            },
                            "value": {
                                "type": [
                                    "string",
                                    "integer"
                                ]
                            }
                        }
                    },
                    "type": "array"
                },
                "title": {
                    "$ref": "#/definitions/StringNullVersioned"
                },
                "description": {
                    "$ref": "#/definitions/StringNullVersioned"
                },
                "status": {
                    "items": {
                        "properties": {
                            "releaseTag": {
                                "items": {
                                    "type": "string"
                                },
                                "type": "array"
                            },
                            "releaseID": {
                                "type": "string"
                            },
                            "releaseDate": {
                                "type": "string",
                                "format": "date-time"
                            },
                            "value": {
                                "type": [
                                    "string",
                                    "null"
                                ],
                                "enum": [
                                    "planned",
                                    "active",
                                    "cancelled",
                                    "unsuccessful",
                                    "complete",
                                    null
                                ]
                            }
                        }
                    },
                    "type": "array"
                },
                "items": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/Item"
                    },
