          "items": {
            "type": "string"
          }
        },
        "github-oauth": {
          "type": "object",
          "description": "A hash of domain name => github API oauth tokens, typically {\"github.com\":\"<token>\"}.",
          "additionalProperties": {
            "type": "string"
          }
        },
        "gitlab-oauth": {
          "type": "object",
