          "type": "string",
          "description": "The location where all binaries are linked, defaults to \"vendor/bin\"."
        },
        "data-dir": {
          "type": "string",
          "description": "The location where old phar files are stored, defaults to \"$home\" except on XDG Base Directory compliant unixes."
