                "Boundaries": {
                    "items": {
                        "$ref": "#/definitions/BoundaryType"
                    },
                    "minItems": 1,
                    "type": "array"
                }
            },
            "required": [
                "Boundaries"
            ],
            "type": "object"
        },
        "FileNameType": {
            "description": "This field describes the name of the actual file.",
            "maxLength": 80,
            "minLength": 1,
            "type": "string"
        },
        "FilePackageType": {
            "additionalProperties": false,
